export const MODULE = "market";
export const ACTIONS = ["calendar.bar_times", "calendar.sessions", "downloads", "estimate_fetch", "export", "fetch", "instruments.get", "instruments.search", "instruments.terms", "read_coverage", "read_data", "read_option_chain", "read_professional", "read_quotes", "read_research", "read_series", "read_source", "scan_import", "write_data", "write_source"] as const;
/** Actions that answer with a task id at once; read the result with platform.tasks. */
export const TASKS = ["export", "fetch", "write_data", "write_source"] as const;
export type Actions = { [K in (typeof ACTIONS)[number]]: ContractTypes[K] };
export function createClient(ctx: Parameters<typeof client>[0]): TypedClient<Actions, (typeof TASKS)[number]> {
  return client<Actions, (typeof TASKS)[number]>(ctx, "market");
}
